 <!-- Col 4: Platform & Resources -->\n        <div>\n          <h4 class=\"text-xs font-bold uppercase tracking-wider text-slate-900 dark:text-white mb-4\">\n            Platform & Guides\n          </h4>\n          <ul class=\"space-y-2.5 text-xs\">\n            <li>\n              <a href=\"/calculators\" class=\"hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors\">All 20 Categories (341+ Tools)</a>\n            </li>\n            <li>\n              <a href=\"#ai-assistant\" class=\"hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors\">Ask CalcDigi AI</a>\n            </li>\n            <li>\n              <a href=\"/pages/blog\" class=\"hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors\">Learning Center & Guides</a>\n            </li>\n            <li>\n              <a href=\"#faq\" class=\"hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors\">Frequently Asked Questions</a>\n            </li>\n            <li>\n              <button type=\"button\" onclick=\"openLegalModal('methodology')\" class=\"text-left hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors cursor-pointer\">\n                Calculation Methodology\n              </button>\n            </li>\n            <li>\n              <button type=\"button\" onclick=\"openLegalModal('changelog')\" class=\"text-left hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors cursor-pointer\">\n                2026 Standards Update\n              </button>\n            </li>\n          </ul>\n        </div>\n\n        <!-- Col 5: Trust, Legal & Google Requirements -->\n        <div>\n          <h4 class=\"text-xs font-bold uppercase tracking-wider text-slate-900 dark:text-white mb-4\">\n            Trust & Legal\n          </h4>\n          <ul class=\"space-y-2.5 text-xs\">\n            <li>\n              <a href=\"/pages/about\" class=\"text-left hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors\">About Us</a>\n            </li>\n            <li>\n              <button type=\"button\" onclick=\"openLegalModal('contact')\" class=\"text-left hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors cursor-pointer\">\n                Contact & Support\n              </button>\n            </li>\n            <li>\n              <button type=\"button\" onclick=\"openLegalModal('privacy')\" class=\"text-left hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors font-semibold text-slate-800 dark:text-slate-200 cursor-pointer\">\n                Privacy Policy\n              </button>\n            </li>\n            <li>\n              <button type=\"button\" onclick=\"openLegalModal('terms')\" class=\"text-left hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors font-semibold text-slate-800 dark:text-slate-200 cursor-pointer\">\n                Terms of Service\n              </button>\n            </li>\n            <li>\n              <button type=\"button\" onclick=\"openLegalModal('disclaimer')\" class=\"text-left hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors cursor-pointer\">\n                Medical & Financial Disclaimer\n              </button>\n            </li>\n            <li>\n              <button type=\"button\" onclick=\"openLegalModal('cookies')\" class=\"text-left hover:text-emerald-600 dark:hover:text-emerald-400 transition-colors cursor-pointer\">\n                Cookie Settings\n              </button>\n            </li>\n          </ul>\n        </div>\n\n      </div>\n\n      <!-- Essential Google Compliance Disclaimer Notice -->\n      <div class=\"py-6 border-b border-slate-200/80 dark:border-slate-800 text-[11px] text-slate-400 dark:text-slate-500 leading-relaxed\">\n        <p>\n          <strong class=\"font-semibold text-slate-600 dark:text-slate-400\">Important Disclaimer:</strong> \n          All calculations, formulas, estimations, and content provided by CalcDigi are designed strictly for educational and general informational purposes. While algorithms are rigorously audited against authoritative sources (including IRS tax brackets, WHO growth standards, and NIST constants), results do not constitute formal medical diagnosis, legal counsel, mortgage lending approval, or certified financial advice. Always verify critical figures with a licensed healthcare provider, certified accountant (CPA), or certified financial advisor before making decisions.\n        </p>\n      </div>\n\n      <!-- Bottom Bar: Copyright & Quick Links -->\n      <div class=\"pt-6 flex flex-col sm:flex-row items-center justify-between gap-4 text-xs text-slate-500 dark:text-slate-400\">\n        <div>\n          &copy; 2026 CalcDigi. All rights reserved. Zero tracking, client-side precision.\n        </div>\n\n        <div class=\"flex items-center gap-4 text-[11px]\">\n          <button type=\"button\" onclick=\"openLegalModal('privacy')\" class=\"hover:underline cursor-pointer\">Privacy</button>\n          <span>•</span>\n          <button type=\"button\" onclick=\"openLegalModal('terms')\" class=\"hover:underline cursor-pointer\">Terms</button>\n          <span>•</span>\n          <button type=\"button\" onclick=\"openLegalModal('disclaimer')\" class=\"hover:underline cursor-pointer\">Disclaimer</button>\n          <span>•</span>\n          <button type=\"button\" onclick=\"openLegalModal('contact')\" class=\"hover:underline cursor-pointer\">Contact</button>\n          <span>•</span>\n          <a href=\"#hero\" class=\"hover:text-emerald-600 dark:hover:text-emerald-400 flex items-center gap-1 font-medium\">\n            <span>Back to top</span>\n            <span>↑</span>\n          </a>\n        </div>\n      </div>\n\n    </div>\n  </footer>\n\n  <!-- ================= GOOGLE COMPLIANCE & LEGAL MODAL ================= -->\n  <div id=\"legal-modal\" style=\"display: none;\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-sm hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[88vh]\">\n      <!-- Modal Header -->\n      <div class=\"p-5 sm:p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between\">\n        <div class=\"flex items-center gap-3\">\n          <div id=\"legal-modal-icon\" class=\"w-10 h-10 rounded-2xl bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400 flex items-center justify-center text-xl font-bold\">\n            ⚖️\n          </div>\n          <div>\n            <div id=\"legal-modal-eyebrow\" class=\"text-[10px] font-bold tracking-widest uppercase text-emerald-700 dark:text-emerald-400\">\n              LEGAL & COMPLIANCE\n            </div>\n            <h3 id=\"legal-modal-title\" class=\"font-serif font-bold text-slate-900 dark:text-white text-base sm:text-lg\">\n              Policy & Terms\n            </h3>\n          </div>\n        </div>\n        <button \n          onclick=\"closeLegalModal()\" \n          class=\"w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-800 dark:hover:text-slate-200 flex items-center justify-center transition-colors\"\n          title=\"Close modal\"\n        >\n          ✕\n        </button>\n      </div>\n\n      <!-- Modal Body -->\n      <div id=\"legal-modal-content\" class=\"p-6 sm:p-8 overflow-y-auto space-y-4 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n        <!-- Injected via JS -->\n      </div>\n\n      <!-- Modal Footer -->\n      <div class=\"p-4 sm:p-5 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/60 flex items-center justify-between\">\n        <span class=\"text-[11px] text-slate-400 dark:text-slate-500\">\n          Last updated: October 2026 • CalcDigi Trust\n        </span>\n        <button \n          onclick=\"closeLegalModal()\" \n          class=\"px-5 py-2 rounded-xl text-xs font-semibold bg-[#18533b] hover:bg-[#12402d] text-white shadow transition-all\"\n        >\n          Understood & Close\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= ARTICLE READER / LEARNING CENTER MODAL ================= -->\n  <div id=\"article-modal\" style=\"display: none;\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-sm hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[88vh]\">\n      <!-- Modal Header -->\n      <div class=\"p-5 sm:p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between\">\n        <div class=\"flex items-center gap-3\">\n          <div id=\"article-modal-icon\" class=\"w-10 h-10 rounded-2xl bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400 flex items-center justify-center text-xl font-bold\">\n            📖\n          </div>\n          <div>\n            <div id=\"article-modal-category\" class=\"text-[10px] font-bold tracking-widest uppercase text-emerald-700 dark:text-emerald-400\">\n              LEARNING CENTER\n            </div>\n            <h3 id=\"article-modal-title\" class=\"font-serif font-bold text-slate-900 dark:text-white text-base sm:text-lg\">\n              Article Preview\n            </h3>\n          </div>\n        </div>\n        <button \n          onclick=\"closeArticleModal()\" \n          class=\"w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 hover:text-slate-800 dark:hover:text-slate-200 flex items-center justify-center transition-colors\"\n          title=\"Close modal\"\n        >\n          ✕\n        </button>\n      </div>\n\n      <!-- Modal Scrollable Content -->\n      <div id=\"article-modal-content\" class=\"p-6 sm:p-8 overflow-y-auto space-y-6 text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n        <!-- Injected via JS -->\n      </div>\n\n      <!-- Modal Footer -->\n      <div class=\"p-4 sm:p-5 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/60 flex items-center justify-between\">\n        <span id=\"article-modal-meta\" class=\"text-xs text-slate-400 dark:text-slate-500 font-medium\">\n          CalcDigi Precision Library\n        </span>\n        <div class=\"flex items-center gap-3\">\n          <button \n            onclick=\"closeArticleModal()\" \n            class=\"px-4 py-2 rounded-xl text-xs font-semibold text-slate-600 dark:text-slate-300 hover:bg-slate-200/50 dark:hover:bg-slate-800 transition-colors\"\n          >\n            Close\n          </button>\n          <a \n            id=\"article-modal-cta\" \n            href=\"#hero\" \n            onclick=\"closeArticleModal()\"\n            class=\"px-5 py-2 rounded-xl text-xs font-semibold bg-[#18533b] hover:bg-[#12402d] text-white shadow transition-all flex items-center gap-1.5\"\n          >\n            <span>Launch Calculator</span>\n            <span>&rarr;</span>\n          </a>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= AI ASSISTANT MODAL ================= -->\n  <div id=\"ai-modal\" style=\"display: none;\" class=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-sm hidden items-center justify-center p-4\">\n    <div class=\"bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[85vh]\">\n      <div class=\"p-4 sm:p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between\">\n        <div class=\"flex items-center gap-2.5\">\n          <div class=\"w-8 h-8 rounded-xl bg-[#046a38] text-white flex items-center justify-center text-sm font-bold\">✨</div>\n          <div>\n            <h3 class=\"font-bold text-sm text-slate-900 dark:text-white\">CalcDigi AI Assistant</h3>\n            <p class=\"text-[11px] text-slate-400\">Ask any calculation or formula question</p>\n          </div>\n        </div>\n        <button onclick=\"closeAiModal()\" class=\"text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 text-lg font-bold p-1\">✕</button>\n      </div>\n\n      <div id=\"ai-chat-box\" class=\"p-4 sm:p-5 flex-1 overflow-y-auto space-y-3 min-h-[220px] text-xs sm:text-sm\">\n        <div class=\"bg-slate-100 dark:bg-slate-800/70 p-3 rounded-2xl text-slate-800 dark:text-slate-200\">\n          👋 <strong>Hi!</strong> I am the CalcDigi AI Assistant. Try asking:\n          <div class=\"mt-2 space-y-1\">\n            <button onclick=\"fillAiPrompt('What is monthly payment on a $450k mortgage at 6.5%?')\" class=\"block w-full text-left p-1.5 rounded-lg bg-white dark:bg-slate-900 text-emerald-600 hover:underline text-xs\">\n              › \"What is monthly payment on a $450k mortgage at 6.5%?\"\n            </button>\n            <button onclick=\"fillAiPrompt('Is a BMI of 23.5 healthy for an adult male?')\" class=\"block w-full text-left p-1.5 rounded-lg bg-white dark:bg-slate-900 text-emerald-600 hover:underline text-xs\">\n              › \"Is a BMI of 23.5 healthy for an adult male?\"\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <form onsubmit=\"handleAiSubmit(event)\" class=\"p-3 sm:p-4 border-t border-slate-100 dark:border-slate-800 flex gap-2\">\n        <input \n          type=\"text\" \n          id=\"ai-prompt-input\" \n          placeholder=\"Ask a calculation question...\" \n          class=\"flex-1 bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-3.5 py-2 text-xs sm:text-sm text-slate-900 dark:text-white outline-none focus:border-emerald-500\"\n        />\n        <button type=\"submit\" class=\"px-4 py-2 rounded-xl bg-[#046a38] hover:bg-[#03542c] text-white font-bold text-xs shadow-xs\">\n          Send\n        </button>\n      </form>\n    </div>\n  </div>\n\n  <!-- ================= JAVASCRIPT LOGIC ================= -->\n  <script>\n    // 1. THEME TOGGLE\n    function toggleTheme() {\n      const html = document.documentElement;\n      const isDark = html.classList.toggle('dark');\n      localStorage.setItem('calcdigi_clone_theme', isDark ? 'dark' : 'light');\n      updateThemeIcon(isDark);\n    }\n    function updateThemeIcon(isDark) {\n      const icon = document.getElementById('theme-moon-icon');\n      if (icon) {\n        icon.textContent = isDark ? '☀️' : '🌙';\n      }\n    }\n    if (localStorage.getItem('calcdigi_clone_theme') === 'dark') {\n      document.documentElement.classList.add('dark');\n      updateThemeIcon(true);\n    }\n\n    // MOBILE NAVIGATION DRAWER (100% Identical to Calculators Drawer)\n    function toggleMobileNav(e) {\n      if (e) e.stopPropagation();\n      const nav = document.getElementById('mobile-nav');\n      const ham = document.getElementById('hamburger-icon');\n      const close = document.getElementById('close-icon');\n      if (!nav) return;\n      const isOpen = nav.classList.toggle('open');\n      if (ham) ham.classList.toggle('hidden', isOpen);\n      if (close) close.classList.toggle('hidden', !isOpen);\n      document.body.style.overflow = isOpen ? 'hidden' : '';\n    }\n\n    document.addEventListener('click', function(e) {\n      const nav = document.getElementById('mobile-nav');\n      const btn = document.getElementById('hamburger') || document.getElementById('mobile-nav-toggle');\n      if (nav && nav.classList.contains('open')) {\n        if (!nav.contains(e.target) && (!btn || !btn.contains(e.target))) {\n          nav.classList.remove('open');\n          const ham = document.getElementById('hamburger-icon');\n          const close = document.getElementById('close-icon');\n          if (ham) ham.classList.remove('hidden');\n          if (close) close.classList.add('hidden');\n          document.body.style.overflow = '';\n        }\n      }\n    });\n\n    document.addEventListener('keydown', function(e) {\n      if (e.key === 'Escape') {\n        const nav = document.getElementById('mobile-nav');\n        if (nav && nav.classList.contains('open')) {\n          nav.classList.remove('open');\n          const ham = document.getElementById('hamburger-icon');\n          const close = document.getElementById('close-icon');\n          if (ham) ham.classList.remove('hidden');\n          if (close) close.classList.add('hidden');\n          document.body.style.overflow = '';\n        }\n      }\n    });\n\n    // 2. HERO CALCULATOR ENGINE (INTERACTIVE 100% WORKING)\n    let currentVal = '2026.42';\n    let previousVal = '';\n    let currentOp = null;\n    let isSciOpen = false;\n\n    function updateDisplay() {\n      const d = document.getElementById('calc-display');\n      d.textContent = currentVal || '0';\n    }\n\n    function appendNum(num) {\n      if (currentVal === '2026.42' || currentVal === '0') {\n        currentVal = num;\n      } else {\n        currentVal += num;\n      }\n      updateDisplay();\n    }\n\n    function appendDot() {\n      if (currentVal === '2026.42') currentVal = '0';\n      if (!currentVal.includes('.')) {\n        currentVal += '.';\n        updateDisplay();\n      }\n    }\n\n    function setOp(op) {\n      currentOp = op;\n      previousVal = currentVal;\n      currentVal = '0';\n      document.getElementById('calc-history').textContent = `${previousVal} ${currentOp}`;\n    }\n\n    function clearCalc() {\n      currentVal = '0';\n      previousVal = '';\n      currentOp = null;\n      document.getElementById('calc-history').textContent = isSciOpen ? 'SCIENTIFIC MODE' : 'BASIC MODE';\n      updateDisplay();\n    }\n\n    function toggleSign() {\n      if (currentVal !== '0') {\n        currentVal = (parseFloat(currentVal) * -1).toString();\n        updateDisplay();\n      }\n    }\n\n    function calcPercent() {\n      currentVal = (parseFloat(currentVal) / 100).toString();\n      updateDisplay();\n    }\n\n    function compute() {\n      if (!currentOp || previousVal === '') return;\n      const p = parseFloat(previousVal);\n      const c = parseFloat(currentVal);\n      let res = 0;\n      switch (currentOp) {\n        case '+': res = p + c; break;\n        case '-': res = p - c; break;\n        case '*': res = p * c; break;\n        case '/': res = c !== 0 ? p / c : 'Error'; break;\n      }\n      document.getElementById('calc-history').textContent = `${previousVal} ${currentOp} ${currentVal} =`;\n      currentVal = (typeof res === 'number') ? (Math.round(res * 100000) / 100000).toString() : res;\n      currentOp = null;\n      previousVal = '';\n      updateDisplay();\n    }\n\n    function calcSci(fn) {\n      const v = parseFloat(currentVal);\n      let r = 0;\n      if (fn === 'sin') r = Math.sin((v * Math.PI) / 180);\n      if (fn === 'cos') r = Math.cos((v * Math.PI) / 180);\n      if (fn === 'tan') r = Math.tan((v * Math.PI) / 180);\n      if (fn === 'sqrt') r = Math.sqrt(v);\n      currentVal = (Math.round(r * 100000) / 100000).toString();\n      updateDisplay();\n    }\n\n    function setHeroCalcMode(mode) {\n      const bBasic = document.getElementById('calc-mode-basic');\n      const bSci = document.getElementById('calc-mode-sci');\n      const sciKeys = document.getElementById('hero-sci-keys');\n\n      if (mode === 'basic') {\n        isSciOpen = false;\n        bBasic.className = 'py-2 text-xs font-bold rounded-lg bg-[#046a38] text-white transition-all shadow-xs';\n        bSci.className = 'py-2 text-xs font-bold rounded-lg bg-[#f1f5f9] dark:bg-slate-800 text-[#64748b] dark:text-slate-300 hover:bg-slate-200 transition-all';\n        sciKeys.classList.add('hidden');\n        sciKeys.classList.remove('grid');\n        document.getElementById('calc-history').textContent = 'BASIC MODE';\n      } else {\n        isSciOpen = true;\n        bSci.className = 'py-2 text-xs font-bold rounded-lg bg-[#046a38] text-white transition-all shadow-xs';\n        bBasic.className = 'py-2 text-xs font-bold rounded-lg bg-[#f1f5f9] dark:bg-slate-800 text-[#64748b] dark:text-slate-300 hover:bg-slate-200 transition-all';\n        sciKeys.classList.remove('hidden');\n        sciKeys.classList.add('grid');\n        document.getElementById('calc-history').textContent = 'SCIENTIFIC MODE';\n      }\n    }\n\n    function setHeroTab(tab) {\n      const tabs = ['calc', 'mortgage', 'bmi', 'percentage', 'calorie'];\n\n      tabs.forEach(t => {\n        const btn = document.getElementById(`hero-nav-${t}`);\n        const view = document.getElementById(`hero-view-${t}`);\n\n        if (btn) {\n          if (t === tab) {\n            btn.className = 'flex items-center gap-1.5 py-1.5 px-3 rounded-xl bg-emerald-50 dark:bg-emerald-950/80 text-[#059669] dark:text-emerald-400 font-bold border border-emerald-200/60 dark:border-emerald-800 shrink-0 transition-all cursor-pointer';\n            btn.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });\n          } else {\n            btn.className = 'flex items-center gap-1.5 py-1.5 px-3 rounded-xl text-[#6b7280] hover:text-slate-900 dark:hover:text-white hover:bg-slate-50 dark:hover:bg-slate-800/60 shrink-0 transition-all cursor-pointer';\n          }\n        }\n\n        if (view) {\n          if (t === tab) {\n            view.classList.remove('hidden');\n            view.classList.add('block');\n          } else {\n            view.classList.add('hidden');\n            view.classList.remove('block');\n          }\n        }\n      });\n\n      if (tab === 'mortgage') updateHeroMortgage();\n      else if (tab === 'bmi') updateHeroBmi();\n      else if (tab === 'percentage') updateHeroPercentage();\n      else if (tab === 'calorie') updateHeroCalorie();\n    }\n\n    function updateHeroPercentage() {\n      const rateInput = document.getElementById('hero-pct-rate');\n      const numInput = document.getElementById('hero-pct-num');\n      if (!rateInput || !numInput) return;\n\n      const rate = parseFloat(rateInput.value);\n      const num = parseFloat(numInput.value);\n      \n      const rateVal = document.getElementById('hero-pct-rate-val');\n      const numVal = document.getElementById('hero-pct-num-val');\n      const resVal = document.getElementById('hero-pct-res');\n      const addVal = document.getElementById('hero-pct-add');\n      const subVal = document.getElementById('hero-pct-sub');\n\n      if (rateVal) rateVal.textContent = `${rate}%`;\n      if (numVal) numVal.textContent = `${num.toLocaleString()}`;\n\n      const res = (rate / 100) * num;\n      if (resVal) resVal.textContent = `${res.toFixed(2)}`;\n      if (addVal) addVal.textContent = (num + res).toFixed(2);\n      if (subVal) subVal.textContent = (num - res).toFixed(2);\n    }\n\n    function setHeroPctRate(rate) {\n      const input = document.getElementById('hero-pct-rate');\n      if (input) {\n        input.value = rate;\n        updateHeroPercentage();\n      }\n    }\n\n    let heroCalGender = 'male';\n    function setHeroCalGender(g) {\n      heroCalGender = g;\n      const bMale = document.getElementById('hero-cal-male');\n      const bFemale = document.getElementById('hero-cal-female');\n      if (bMale && bFemale) {\n        if (g === 'male') {\n          bMale.className = 'px-2.5 py-1 rounded-lg bg-emerald-600 text-white shadow-xs transition-all';\n          bFemale.className = 'px-2.5 py-1 rounded-lg text-slate-600 dark:text-slate-300 hover:text-slate-900 transition-all';\n        } else {\n          bFemale.className = 'px-2.5 py-1 rounded-lg bg-emerald-600 text-white shadow-xs transition-all';\n          bMale.className = 'px-2.5 py-1 rounded-lg text-slate-600 dark:text-slate-300 hover:text-slate-900 transition-all';\n        }\n      }\n      updateHeroCalorie();\n    }\n\n    function updateHeroCalorie() {\n      const ageInput = document.getElementById('hero-cal-age');\n      const wInput = document.getElementById('hero-cal-w');\n      const hInput = document.getElementById('hero-cal-h');\n      if (!ageInput || !wInput || !hInput) return;\n\n      const age = parseFloat(ageInput.value);\n      const w = parseFloat(wInput.value);\n      const h = parseFloat(hInput.value);\n\n      const ageVal = document.getElementById('hero-cal-age-val');\n      const wVal = document.getElementById('hero-cal-w-val');\n      const hVal = document.getElementById('hero-cal-h-val');\n      const resVal = document.getElementById('hero-cal-res');\n      const lossVal = document.getElementById('hero-cal-loss');\n      const gainVal = document.getElementById('hero-cal-gain');\n\n      if (ageVal) ageVal.textContent = `${age} yrs`;\n      if (wVal) wVal.textContent = `${w} kg`;\n      if (hVal) hVal.textContent = `${h} cm`;\n\n      // Mifflin-St Jeor Formula\n      let bmr = (10 * w) + (6.25 * h) - (5 * age);\n      if (heroCalGender === 'male') {\n        bmr += 5;\n      } else {\n        bmr -= 161;\n      }\n\n      // Moderate activity multiplier (1.45 for general healthy baseline)\n      const maintenance = Math.round(bmr * 1.45);\n      const loss = Math.max(1200, maintenance - 500);\n      const gain = maintenance + 300;\n\n      if (resVal) resVal.textContent = `${maintenance.toLocaleString()} kcal`;\n      if (lossVal) lossVal.textContent = `${loss.toLocaleString()} kcal`;\n      if (gainVal) gainVal.textContent = `${gain.toLocaleString()} kcal`;\n    }\n\n    function setPercentagePreset() {\n      currentVal = '37.50';\n      document.getElementById('calc-history').textContent = '15% of 250 =';\n      updateDisplay();\n    }\n\n    // Keyboard support for hero calculator\n    document.addEventListener('keydown', (e) => {\n      if (['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName)) return;\n      if (e.key >= '0' && e.key <= '9') appendNum(e.key);\n      if (e.key === '.') appendDot();\n      if (e.key === '+') setOp('+');\n      if (e.key === '-') setOp('-');\n      if (e.key === '*' || e.key === 'x' || e.key === 'X') setOp('*');\n      if (e.key === '/') setOp('/');\n      if (e.key === 'Enter' || e.key === '=') { e.preventDefault(); compute(); }\n      if (e.key === 'Escape' || e.key === 'c' || e.key === 'C') clearCalc();\n      if (e.key === '%') calcPercent();\n    });\n\n    function updateHeroMortgage() {\n      const price = parseFloat(document.getElementById('hero-mort-price').value);\n      const down = parseFloat(document.getElementById('hero-mort-down').value);\n      const downPct = Math.round((down / price) * 100);\n      document.getElementById('hero-mort-price-val').textContent = `$${price.toLocaleString()}`;\n      document.getElementById('hero-mort-down-val').textContent = `$${down.toLocaleString()} (${downPct}%)`;\n\n      const loan = price - down;\n      const r = (6.5 / 100) / 12;\n      const n = 360;\n      const p = (loan * (r * Math.pow(1 + r, n))) / (Math.pow(1 + r, n) - 1);\n      document.getElementById('hero-mort-res').textContent = `$${p.toFixed(2)}`;\n    }\n\n    function updateHeroBmi() {\n      const h = parseFloat(document.getElementById('hero-bmi-h').value);\n      const w = parseFloat(document.getElementById('hero-bmi-w').value);\n      document.getElementById('hero-bmi-h-val').textContent = `${h} cm`;\n      document.getElementById('hero-bmi-w-val').textContent = `${w} kg`;\n      const bmi = w / ((h / 100) * (h / 100));\n      document.getElementById('hero-bmi-res').textContent = bmi.toFixed(1);\n    }\n\n    // 3. CATEGORIES & CALCULATORS DIRECTORY SEARCH & EXPAND\n    const ALL_CALCULATORS_DB = [{\"n\":\"BMI Calculator\",\"i\":\"⚖️\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/bmi-calculator\"},{\"n\":\"Calorie Calculator\",\"i\":\"🥗\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/calorie-calculator\"},{\"n\":\"TDEE Calculator\",\"i\":\"⚡\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/tdee-calculator\"},{\"n\":\"BMR Calculator\",\"i\":\"🔥\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/bmr-calculator\"},{\"n\":\"Macro Calculator\",\"i\":\"🧬\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/macro-calculator\"},{\"n\":\"Ideal Weight Calculator\",\"i\":\"🏋️\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/ideal-weight-calculator\"},{\"n\":\"Body Fat Calculator\",\"i\":\"📊\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/body-fat-calculator\"},{\"n\":\"Water Intake Calculator\",\"i\":\"💧\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/water-intake-calculator\"},{\"n\":\"Protein Intake Calculator\",\"i\":\"🥩\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/protein-intake-calculator\"},{\"n\":\"Heart Rate Zone Calculator\",\"i\":\"❤️\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/heart-rate-zone-calculator\"},{\"n\":\"Weight Loss Calculator\",\"i\":\"📉\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/weight-loss-calculator\"},{\"n\":\"Lean Body Mass Calculator\",\"i\":\"💪\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/lean-body-mass-calculator\"},{\"n\":\"Pregnancy Due Date Calculator\",\"i\":\"🤰\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/pregnancy-due-date-calculator\"},{\"n\":\"Ovulation Calculator\",\"i\":\"📅\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/ovulation-calculator\"},{\"n\":\"Sleep Calculator\",\"i\":\"😴\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/sleep-calculator\"},{\"n\":\"Pace Calculator\",\"i\":\"🏃\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/pace-calculator\"},{\"n\":\"VO2 Max Calculator\",\"i\":\"🫁\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/vo2-max-calculator\"},{\"n\":\"One Rep Max Calculator\",\"i\":\"🏋️\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/one-rep-max-calculator\"},{\"n\":\"Waist to Hip Ratio\",\"i\":\"📏\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/waist-to-hip-ratio-calculator\"},{\"n\":\"Blood Pressure Analyzer\",\"i\":\"💊\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/blood-pressure-calculator\"},{\"n\":\"Bra Size Calculator\",\"i\":\"👙\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/bra-size-calculator\"},{\"n\":\"Period Calculator\",\"i\":\"🌸\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/period-calculator\"},{\"n\":\"Fertility Calculator\",\"i\":\"🌺\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/fertility-calculator\"},{\"n\":\"Baby Weight Calculator\",\"i\":\"👶\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/baby-weight-calculator\"},{\"n\":\"Child Height Predictor\",\"i\":\"📐\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/child-height-predictor\"},{\"n\":\"Pushup Fitness Test\",\"i\":\"💪\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/pushup-test-calculator\"},{\"n\":\"Swim Pace Calculator\",\"i\":\"🏊\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/swim-pace-calculator\"},{\"n\":\"Cycling Calculator\",\"i\":\"🚴\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/cycling-calculator\"},{\"n\":\"Calorie Burn Calculator\",\"i\":\"🔥\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/calorie-burn-calculator\"},{\"n\":\"Steps to Calories\",\"i\":\"👟\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/steps-to-calories-calculator\"},{\"n\":\"Intermittent Fasting\",\"i\":\"⏱️\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/intermittent-fasting-calculator\"},{\"n\":\"Alcohol Unit Calculator\",\"i\":\"🍷\",\"c\":\"Health & Fitness\",\"e\":\"🩺\",\"u\":\"/calculators/health/alcohol-unit-calculator\"},{\"n\":\"Smoking Cost Calculator\",\"i\":\"🚬\",\"c